#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    string text = "Hello World! How are you?";
    map<char, int> charCount;

    for (char c : text) {
        if (isalnum(c)) {
            c = tolower(c);
            charCount[c]++;
        }
    }

    cout << "原文本: " << text << endl;
    cout << "
字符出现频率:" << endl;

    for (auto& pair : charCount) {
        cout << "'" << pair.first << "': " << pair.second << endl;
    }

    char mostCommon = charCount.begin()->first;
    int maxCount = charCount.begin()->second;
    for (auto& pair : charCount) {
        if (pair.second > maxCount) {
            mostCommon = pair.first;
            maxCount = pair.second;
        }
    }

    cout << "
出现最多的字符: '" << mostCommon << "' (" << maxCount << "次)" << endl;

    return 0;
}
